/// <summary>
/// The census verdict for one auto-wrong line: one relation (accepted row vs key row) and one site
/// (where the line was accepted), plus the audit fields the TSV emits.
/// </summary>
/// <param name="HoldoutId">The line's holdout id.</param>
/// <param name="LineIndex">The line index within the recipe.</param>
/// <param name="Set">The trace set (<c>debug</c> or <c>batch</c>).</param>
/// <param name="Relation">One of: no-label, pack-unit-state, compound-head-lost, state-mismatch, row-choice-tier, same-head-other-qualifier, sibling-food, other.</param>
/// <param name="Site">One of: reuse, override, curated, ranker. <see langword="null"/> when the atom's path was not one of the three production paths.</param>
/// <param name="OverrideKey">For <c>override</c> sites only: <c>yes</c>/<c>no</c> — whether the normalised rawText is a key of <c>exact-overrides.json</c>.</param>
/// <param name="AcceptedTier">The accepted row's data type.</param>
/// <param name="KeyTier">The key row's data type.</param>
/// <param name="AcceptedState">The accepted row's <c>FoodState</c> mask (state | satisfiers).</param>
/// <param name="KeyState">The key row's <c>FoodState</c> mask (state | satisfiers).</param>
/// <param name="ParsedName">The atom's parsed name, verbatim.</param>
/// <param name="KeyHead">The key's head phrase (head term plus leading non-modifier tokens), singularised.</param>
/// <param name="AcceptedDesc">The accepted description.</param>
/// <param name="KeyDesc">The key description.</param>
/// <param name="RawText">The raw line text.</param>
/// <param name="MissingField">The trace field whose absence forced <c>other</c>, when one did.</param>
/// <param name="QualifierDiff">For <c>same-head-other-qualifier</c>: the qualifier words present on one side only.</param>
/// <param name="TierDirection">For <c>row-choice-tier</c>: which tier is higher, <c>key</c> or <c>accepted</c>.</param>
public sealed record ClassificationResult(
	string HoldoutId,
	int LineIndex,
	string Set,
	string Relation,
	string? Site,
	string? OverrideKey,
	string AcceptedTier,
	string KeyTier,
	string AcceptedState,
	string KeyState,
	string ParsedName,
	string KeyHead,
	string AcceptedDesc,
	string KeyDesc,
	string RawText,
	string? MissingField,
	string? QualifierDiff,
	string? TierDirection);
