{"content":"namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>
/// The census classification of one auto-wrong line: exactly one <see cref="Relation"/> and one
/// <see cref="Site"/>, plus the audit fields the TSV carries.
/// </summary>
public sealed record ClassificationResult
{
	/// <summary>Relation <c>no-label</c>: the line has no labelled row.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation <c>pack-unit-state</c>: a can/jar unit line whose key row is canned and the accepted row is not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation <c>compound-head-lost</c>: the key's head phrase is two or more words and the parsed name kept only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation <c>state-mismatch</c>: same head, different <c>FoodState</c> masks.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation <c>row-choice-tier</c>: same head and state, different dataset tier.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation <c>same-head-other-qualifier</c>: same head, state, and tier; only the remaining qualifiers differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation <c>sibling-food</c>: the head terms of the two rows differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation <c>other</c>: no rule held, or a field the rule needs is missing from the trace.</summary>
	public const string RelationOther = "other";

	/// <summary>Site <c>reuse</c>: ranker path on a reused master row.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site <c>override</c>: the exact/slug/core override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site <c>curated</c>: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site <c>ranker</c>: ranked, not reused.</summary>
	public const string SiteRanker = "ranker";

	/// <summary>Holdout id of the line.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Line index within the recipe.</summary>
	public int LineIndex { get; init; }

	/// <summary>Trace set (<c>debug</c> or <c>batch</c>).</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>The winning relation.</summary>
	public string Relation { get; init; } = string.Empty;

	/// <summary>The decision site; <c>null</c> when the atom's path is unknown and the run must fail.</summary>
	public string? Site { get; init; }

	/// <summary><c>yes</c>/<c>no</c> for override-site lines: the normalised raw text is a key of <c>exact-overrides.json</c>; empty otherwise.</summary>
	public string OverrideKey { get; init; } = string.Empty;

	/// <summary>Dataset tier of the accepted row.</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>Dataset tier of the key row.</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>Accepted row's <c>FoodState</c> mask (state words plus satisfiers).</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>Key row's <c>FoodState</c> mask (state words plus satisfiers).</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name, verbatim.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>The key row's head phrase (head term plus the leading non-state qualifier words), singularised.</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>The accepted row's description.</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>The key row's description.</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>The raw recipe line.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>Which tier is higher for <c>row-choice-tier</c> lines: <c>key</c>, <c>accepted</c>, or empty.</summary>
	public string TierDirection { get; init; } = string.Empty;

	/// <summary>For <c>same-head-other-qualifier</c> lines: the qualifier words only the key row carries, comma-joined.</summary>
	public string KeyOnlyQualifiers { get; init; } = string.Empty;

	/// <summary>For <c>same-head-other-qualifier</c> lines: the qualifier words only the accepted row carries, comma-joined.</summary>
	public string AcceptedOnlyQualifiers { get; init; } = string.Empty;

	/// <summary>Trace field a needed rule could not read (e.g. <c>actualDataTypes</c>); empty when all fields were present.</summary>
	public string MissingField { get; init; } = string.Empty;
}
