{"content":"using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — relation (accepted row vs key row) and site
/// (how the row was decided) — using the production helpers only: <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse"/>, <see cref="IngredientLineResolver.SingularizeToken"/> and
/// <see cref="IngredientLineResolver.ShouldReuse"/> (F-428 P12.13, D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: raw line carries a can/jar unit; the key row is canned, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tiers differ.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head, state and tier agree and only the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds, or a field the check needs is missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row via the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path decided the row.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue decided the row.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker picked the row without reuse.</summary>
	public const string SiteRanker = "ranker";

	private static readonly string[] AllowedSets = ["debug", "batch"];

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The key index of <c>exact-overrides.json</c>.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>The trace sets the census may read; anything else is refused (D-029).</summary>
	public static IReadOnlyList<string> AllowedSets => AllowedSets;

	/// <summary>
	/// Classifies one auto-wrong line. The first relation rule that holds wins (brief §4 order);
	/// a missing field a check needs sends the line to <see cref="Other"/> with <see cref="ClassificationResult.MissingField"/>.
	/// </summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault(string.IsNullOrEmpty) is null
			? line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty
			: string.Empty;
		var accDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var accTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();

		var site = atom is null ? string.Empty : SiteOf(atom, line.RawText);
		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var accTokens = _normalizer.NormalizeToTokens(accDesc);
		var keyState = CombinedState(keyTokens);
		var accState = CombinedState(accTokens);
		var keyHead = HeadTokens(keyDesc, keyTier);
		var accHead = HeadTokens(accDesc, accTier);
		var parsedNameTokens = SingularTokens(atom?.ParsedName ?? string.Empty);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		string relation;
		string? missingField = null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = NoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (accState & FoodState.Canned) == FoodState.None)
		{
			relation = PackUnitState;
		}
		else if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = CompoundHeadLost;
		}
		else if (HeadsAgree(keyHead, accHead))
		{
			if (keyState != accState)
			{
				relation = StateMismatch;
			}
			else if (string.IsNullOrEmpty(keyTier) || string.IsNullOrEmpty(accTier))
			{
				relation = Other;
				missingField = string.IsNullOrEmpty(accTier) ? "actualDataTypes" : "expectedDataTypes";
			}
			else if (!string.Equals(keyTier, accTier, StringComparison.OrdinalIgnoreCase))
			{
				relation = RowChoiceTier;
			}
			else
			{
				relation = SameHeadOtherQualifier;
				(keyOnlyQualifiers, acceptedOnlyQualifiers) = QualifierDiff(keyDesc, keyTier, accDesc, accTier);
			}
		}
		else
		{
			relation = SiblingFood;
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = site == SiteOverride ? (_overrideKeys.Contains(OverrideKeyCandidate(line.RawText)) ? "yes" : "no") : string.Empty,
			AcceptedTier = accTier,
			KeyTier = keyTier,
			AcceptedState = accState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = accDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key head phrase: the key row's normalized tokens up to the first token the production
	/// state/modifier vocabulary flags (modifier words, or a token <see cref="FdcMatcher.ExtractCandidateState"/>
	/// / <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> reports as state). "Bread, crumbs, dry, grated, plain"
	/// gives <c>bread crumbs</c>; "Tomatoes, crushed, canned" gives <c>tomato</c>.
	/// </summary>
	/// <param name="keyTokens">The key row's normalized tokens.</param>
	/// <returns>The leading non-state tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (IsStateOrModifierToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask of a description: <see cref="FdcMatcher.ExtractCandidateState"/> ∪
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> on its normalized tokens — the same composition
	/// <c>FdcMatcher</c> feeds to <c>StateAgrees</c>.
	/// </summary>
	/// <param name="tokens">Normalized description tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Whether the production reuse rule (<see cref="IngredientLineResolver.ShouldReuse"/>) would match the
	/// line's parsed name against its linked master slug — the census's reuse-site diagnostic.
	/// </summary>
	/// <param name="parsedName">The parser name from the trace atom.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>The production verdict; false when either side is empty.</returns>
	public static bool ReuseRuleMatches(string parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(parsedName) || string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return false;
		}

		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);
	}

	private static string SiteOf(TraceAtom atom, string rawText) => atom.Path switch
	{
		"override" => SiteOverride,
		"curated" => SiteCurated,
		"ranker" => atom.Reused ? SiteReuse : SiteRanker,
		_ => string.Empty,
	};

	private static bool HeadsAgree(IReadOnlyList<string> a, IReadOnlyList<string> b) =>
		a.Count == b.Count && a.Zip(b).All(p => string.Equals(p.First, p.Second, StringComparison.OrdinalIgnoreCase));

	private static string OverrideKeyCandidate(string rawText)
	{
		// Production's raw-key lookup normalizes by cutting at the first '(' and lowercasing
		// (FdcMatcher.MatchAsync, nameClean). StripFromParenthesis is private, so the cut is
		// applied here and the lookup itself is the production key index.
		var cut = rawText.IndexOf('(', StringComparison.Ordinal);
		var cleaned = (cut >= 0 ? rawText[..cut] : rawText).Trim();
		return cleaned.Length == 0 ? rawText.Trim() : cleaned;
	}

	private (IReadOnlyList<string>, IReadOnlyList<string>) QualifierDiff(
		string keyDesc, string keyTier, string accDesc, string accTier)
	{
		var keyQualifiers = SingularTokens(string.Join(' ', FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers));
		var accQualifiers = SingularTokens(string.Join(' ', FdcDescriptionParser.Parse(accDesc, DatasetOf(accTier)).Qualifiers));
		var keySet = new HashSet<string>(keyQualifiers, StringComparer.OrdinalIgnoreCase);
		var accSet = new HashSet<string>(accQualifiers, StringComparer.OrdinalIgnoreCase);
		var keyOnly = keyQualifiers.Where(q => !accSet.Contains(q)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(q => q, StringComparer.OrdinalIgnoreCase).ToArray();
		var accOnly = accQualifiers.Where(q => !keySet.Contains(q)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(q => q, StringComparer.OrdinalIgnoreCase).ToArray();
		return (keyOnly, accOnly);
	}

	private IReadOnlyList<string> HeadTokens(string desc, string tier)
	{
		if (string.IsNullOrWhiteSpace(desc))
		{
			return [];
		}

		return SingularTokens(FdcDescriptionParser.Parse(desc, DatasetOf(tier)).HeadTerm);
	}

	private IReadOnlyList<string> SingularTokens(string text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private bool IsStateOrModifierToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();
}
