{"content":"using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes (F-428 P12.13):
/// <see cref="ClassificationResult.Relation"/> (accepted row vs key row) and
/// <see cref="ClassificationResult.Site"/> (where the line was accepted).
/// Every row comparison goes through the production helpers — <see cref="FdcNormalizer.NormalizeToTokens(string)"/>,
/// <see cref="FdcMatcher.ExtractCandidateState(System.Collections.Generic.IReadOnlyList{string})"/> /
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(System.Collections.Generic.IReadOnlyList{string})"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset)"/>, <see cref="IngredientLineResolver.SingularizeToken(string)"/>
/// and the <see cref="FdcLexicon.Default"/> modifier set — never a copy of their logic (D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the key line has no label.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw line, the key row is <see cref="FoodState.Canned"/> and the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is multi-word and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: heads agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: heads and state agree and the dataset tiers differ.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: heads, state and tier agree; the qualifier words differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the heads differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above held, or a field a check needed was missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path accepted the line.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue accepted the line.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker accepted a fresh row.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Single-element scratch for the per-token state probe; the runner is single-threaded.
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier.</summary>
	/// <param name="normalizer">The production token normalizer.</param>
	/// <param name="overrideKeys">The exact-overrides key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>Classifies one auto-wrong line; <c>Site</c> is empty when the atom path is unknown.</summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The relation and site for the line.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => string.Equals(a.Outcome, "accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		var parsedName = SingularPhrase(atom?.ParsedName ?? string.Empty);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		var site = SiteOf(atom);
		var overrideKey = string.Empty;
		if (site == SiteOverride)
		{
			overrideKey = _overrideKeys.IsKey(FoldForOverrideKey(line.RawText)) ? "yes" : "no";
		}

		var relation = Other;
		var missingField = (string?)null;
		var keyOnlyQualifiers = (IReadOnlyList<string>?)null;
		var acceptedOnlyQualifiers = (IReadOnlyList<string>?)null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = NoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != FoodState.None && (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = PackUnitState;
		}
		else if (keyPhrase.Count >= 2 && parsedName.Count == 1
			&& string.Equals(parsedName[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = CompoundHeadLost;
		}
		else if (keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase))
		{
			if (keyState != acceptedState)
			{
				relation = StateMismatch;
			}
			else if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				missingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
			}
			else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				relation = RowChoiceTier;
			}
			else
			{
				relation = SameHeadOtherQualifier;
				var keyQualifiers = SingularPhrase(string.Join(' ', FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers));
				var acceptedQualifiers = SingularPhrase(string.Join(' ', FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers));
				keyOnlyQualifiers = keyQualifiers.Where(q => !acceptedQualifiers.Contains(q, StringComparer.OrdinalIgnoreCase)).OrderBy(q => q, StringComparer.OrdinalIgnoreCase).ToArray();
				acceptedOnlyQualifiers = acceptedQualifiers.Where(q => !keyQualifiers.Contains(q, StringComparer.OrdinalIgnoreCase)).OrderBy(q => q, StringComparer.OrdinalIgnoreCase).ToArray();
			}
		}
		else
		{
			relation = SiblingFood;
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key head phrase: the key description's tokens up to (not including) the first token that
	/// production treats as a state or modifier word — <see cref="FdcLexicon.ModifierWords"/> or a
	/// non-empty <see cref="FdcMatcher.ExtractCandidateState(System.Collections.Generic.IReadOnlyList{string})"/> /
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(System.Collections.Generic.IReadOnlyList{string})"/> mask.
	/// "Bread, crumbs, dry, grated, plain" → <c>bread crumbs</c>; "Nuts, almonds, blanched" → <c>nut almond</c>.
	/// </summary>
	/// <param name="keyTokens">The key description's normalized tokens.</param>
	/// <returns>The leading head tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (IsStateOrModifierToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>The state ∪ satisfiers mask of a token list — the two production extraction passes combined.</summary>
	/// <param name="tokens">Normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>Folds a raw line the way the override path keys it: lower-case, trimmed, content from the first <c>(</c> dropped.</summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string FoldForOverrideKey(string rawText)
	{
		var text = rawText.Trim().ToLowerInvariant();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		return (paren >= 0 ? text[..paren] : text).Trim();
	}

	/// <summary>Whether the dataset tier string names a known <see cref="FdcDataset"/>; <see cref="FdcDataset.None"/> when it does not.</summary>
	/// <param name="tier">The trace tier string.</param>
	/// <returns>The dataset, or <see cref="FdcDataset.None"/>.</returns>
	public static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true) ? Enum.Parse<FdcDataset>(tier, ignoreCase: true) : FdcDataset.None;

	private static string SiteOf(TraceAtom? atom)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private bool IsStateOrModifierToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return CombinedState(_singleToken) != FoodState.None;
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();
}
