{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes (F-428 P12.13): the relation between the
/// accepted row and the labelled (key) row, and the decision site. Every matcher fact comes from
/// the production helpers — <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse"/>, <see cref="IngredientLineResolver.SingularizeToken"/> —
/// never a re-implementation (D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the key row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw text, the key is <see cref="FoodState.Canned"/>, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tiers differ.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head, state and tier agree and only the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds, or a relation check lacked a trace field.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing master/row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override / special-cases path decided the row.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue decided the row.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker picked the row without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Single-threaded scratch for the per-token production state checks; the runner classifies sequentially.
	private readonly string?[] _singleTokenScratch = [null!];

	/// <summary>Creates the classifier over the production normalizer and the override key index.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> raw-key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// The state mask a description carries: the production candidate state plus its satisfiers,
	/// the same composition <c>FdcMatcher</c> feeds to <c>StateAgrees</c>.
	/// </summary>
	/// <param name="tokens">Normalized description tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// The key head phrase: the key's normalized tokens up to (excluding) the first token the
	/// production lexicon/matcher treats as a state or modifier word — "Bread, crumbs, dry, grated,
	/// plain" is <c>bread crumbs</c>; "Nuts, almonds, blanched" is <c>nut almond</c>.
	/// </summary>
	/// <param name="tokens">Normalized key description tokens.</param>
	/// <returns>The head phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// Classifies one auto-wrong line (<c>auto == true &amp;&amp; correct == false</c>).
	/// </summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path was unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;
		var site = SiteOf(atom);
		var overrideKey = site == SiteOverride ? (_overrideKeys.IsKey(FoldForOverrideKey(line.RawText)) ? "yes" : "no") : string.Empty;

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			ParsedName = parsedName,
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = NoLabel;
			return result;
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		result.KeyState = keyState.ToString();
		result.AcceptedState = acceptedState.ToString();

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = string.IsNullOrWhiteSpace(acceptedDesc)
			? new ParsedFdcDescription(string.Empty, [], null)
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = SingularPhrase(acceptedParsed.HeadTerm);
		result.KeyHead = string.Join(' ', keyHead);

		var parsedNameTokens = SingularPhrase(parsedName);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != FoodState.None && (acceptedState & FoodState.Canned) == FoodState.None)
		{
			result.Relation = PackUnitState;
			return result;
		}

		if (keyPhrase.Count >= 2 && parsedNameTokens.Count == 1 &&
			string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = CompoundHeadLost;
			return result;
		}

		if (!HeadsAgree(keyHead, acceptedHead))
		{
			result.Relation = SiblingFood;
			return result;
		}

		if (keyState != acceptedState)
		{
			result.Relation = StateMismatch;
			return result;
		}

		if (string.IsNullOrEmpty(keyTier) || string.IsNullOrEmpty(acceptedTier))
		{
			result.Relation = Other;
			result.MissingField = string.IsNullOrEmpty(acceptedTier) ? nameof(TraceLine.ActualDataTypes) : nameof(TraceLine.ExpectedDataTypes);
			return result;
		}

		if (keyTier != acceptedTier)
		{
			result.Relation = RowChoiceTier;
			return result;
		}

		result.Relation = SameHeadOtherQualifier;
		(result.KeyOnlyQualifiers, result.AcceptedOnlyQualifiers) = QualifierDiff(keyParsed.Qualifiers, acceptedParsed.Qualifiers);
		return result;
	}

	/// <summary>Folds a raw line the way the production raw-key override lookup does: lower-case, trimmed, content from the first <c>(</c> dropped.</summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup text.</returns>
	public static string FoldForOverrideKey(string rawText)
	{
		var index = rawText.IndexOf('(', StringComparison.Ordinal);
		var cut = index >= 0 ? rawText[..index] : rawText;
		return cut.Trim().ToLowerInvariant();
	}

	private string SiteOf(TraceAtom? atom)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	private bool CarriesStateToken(string token) =>
		FdcLexicon.Default.ModifierWords.Contains(token)
		|| FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
		|| FdcMatcher.ExtargetCandidateSatisfiers(_singleTokenScratch) != FoodState.None;

	private static bool HeadsAgree(IReadOnlyList<string> a, IReadOnlyList<string> b) =>
		a.Count == b.Count && a.Zip(b).All(p => string.Equals(p.First, p.Second, StringComparison.OrdinalIgnoreCase));

	private static (IReadOnlyList<string> KeyOnly, IReadOnlyList<string> AcceptedOnly) QualifierDiff(
		IReadOnlyList<string> keyQualifiers,
		IReadOnlyList<string> acceptedQualifiers)
	{
		var keySet = new HashSet<string>(keyQualifiers, StringComparer.OrdinalIgnoreCase);
		var acceptedSet = new HashSet<string>(acceptedQualifiers, StringComparer.OrdinalIgnoreCase);
		var keyOnly = keySet.Where(q => !acceptedSet.Contains(q)).OrderBy(q => q, StringComparer.Ordinal).ToArray();
		var acceptedOnly = acceptedSet.Where(q => !keySet.Contains(q)).OrderBy(q => q, StringComparer.Ordinal).ToArray();
		return (keyOnly, acceptedOnly);
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static FdcDataset DatasetOf(string? tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true) ? Enum.Parse<FdcDataset>(tier!, ignoreCase: true) : FdcDataset.None;

	private static string First(IReadOnlyList<string> values) =>
		values.Count > 0 && !string.IsNullOrWhiteSpace(values[0]) ? values[0] : string.Empty;
}
