{"content":"using System.Text;
using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: reads a HoldoutGate trace JSONL, refuses any set other than <c>debug</c> or
/// <c>batch</c> (D-029), classifies every <c>auto &amp;&amp; !correct</c> line through
/// <see cref="AutoWrongClassifier"/>, and writes the TSV to stdout and the relation × site summary
/// to stderr.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private const string CensusHeader = "holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (string.IsNullOrEmpty(_options.Command))
		{
			await writers.Error.WriteLineAsync("Unusable arguments. Usage:").ConfigureAwait(false);
			await writers.Error.WriteLineAsync("  census <trace.jsonl>").ConfigureAwait(false);
			await writers.Error.WriteLineAsync("  pairs <census.tsv> <trace.jsonl>").ConfigureAwait(false);
			return 1;
		}

		if (!File.Exists(_options.TracePath))
		{
			await writers.Error.WriteLineAsync($"Trace file not found at '{_options.TracePath}'.").ConfigureAwait(false);
			return 1;
		}

		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var rejected = lines.FirstOrDefault(l => !l.Set.Equals("debug", StringComparison.Ordinal) && !l.Set.Equals("batch", StringComparison.Ordinal));
		if (rejected is not null)
		{
			await writers.Error.WriteLineAsync($"Refusing trace line {rejected.HoldoutId}#{rejected.LineIndex}: set '{rejected.Set}' is not debug or batch (D-029).").ConfigureAwait(false);
			return 1;
		}

		if (_options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase))
		{
			return await RunCensusAsync(lines, cancellationToken).ConfigureAwait(false);
		}

		return await RunPairsAsync(lines, cancellationToken).ConfigureAwait(false);
	}

	private async Task<int> RunCensusAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();

		await writers.Output.WriteLineAsync(CensusHeader).ConfigureAwait(false);
		foreach (var line in autoWrong)
		{
			cancellationToken.ThrowIfCancellationRequested();
			var result = classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				await writers.Error.WriteLineAsync($"Unknown atom path '{FirstAtom(line).Path}' on {line.HoldoutId}#{line.LineIndex}; refusing to classify silently.").ConfigureAwait(false);
				return 1;
			}

			await writers.Output.WriteLineAsync(ToTsv(result)).ConfigureAwait(false);
		}

		await WriteSummaryAsync(lines.Count, autoWrong, cancellationToken).ConfigureAwait(false);
		return 0;
	}

	private async Task<int> RunPairsAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		if (!File.Exists(_options.CensusTsvPath))
		{
			await writers.Error.WriteLineAsync($"Census TSV not found at '{_options.CensusTsvPath}'.").ConfigureAwait(false);
			return 1;
		}

		var rows = await Task.Run(() => File.ReadLines(_options.CensusTsvPath).ToList(), cancellationToken).ConfigureAwait(false);
		if (rows.Count == 0)
		{
			await writers.Error.WriteLineAsync($"Census TSV '{_options.CensusTsvPath}' is empty.").ConfigureAwait(false);
			return 1;
		}

		var header = rows[0].Split('\t');
		var idColumn = header.ToList().IndexOf("holdoutId");
		var indexColumn = header.ToList().IndexOf("lineIndex");
		var blockerColumn = header.ToList().IndexOf("blocker");
		var routeColumn = header.ToList().IndexOf("route");
		if (idColumn < 0 || indexColumn < 0 || blockerColumn < 0 || routeColumn < 0)
		{
			await writers.Error.WriteLineAsync($"Census TSV header is missing holdoutId/lineIndex/blocker/route columns: '{string.Join(' ', header)}'.").ConfigureAwait(false);
			return 1;
		}

		var byLine = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		await writers.Output.WriteLineAsync(PairsHeader).ConfigureAwait(false);

		var emitted = 0;
		var unmatched = 0;
		for (var i = 1; i < rows.Count; i++)
		{
			cancellationToken.ThrowIfCancellationRequested();
			var cells = rows[i].Split('\t');
			if (cells.Length <= Math.Max(idColumn, Math.Max(indexColumn, Math.Max(blockerColumn, routeColumn))))
			{
				continue;
			}

			if (!cells[blockerColumn].Equals("window", StringComparison.Ordinal)
				|| (!cells[routeColumn].Equals("compound", StringComparison.Ordinal) && !cells[routeColumn].Equals("other", StringComparison.Ordinal)))
			{
				continue;
			}

			if (!byLine.TryGetValue((cells[idColumn], int.Parse(cells[indexColumn])), out var line))
			{
				unmatched++;
				continue;
			}

			var parsedNameHead = string.Join(' ', Fold(line.Atoms[0].ParsedName));
			var keyHead = line.ExpectedDescriptions.Count > 0
				? string.Join(' ', classifier.KeyHeadPhrase(new FdcNormalizer().NormalizeToTokens(line.ExpectedDescriptions[0])))
				: string.Empty;
			await writers.Output.WriteLineAsync(string.Join('\t', Sanitize(cells[idColumn]), line.LineIndex, Sanitize(parsedNameHead), Sanitize(keyHead), Sanitize(line.RawText))).ConfigureAwait(false);
			emitted++;
		}

		await writers.Error.WriteLineAsync($"pairs: emitted={emitted} unmatched={unmatched} (census rows without a trace line).").ConfigureAwait(false);
		return 0;
	}

	private async Task WriteSummaryAsync(int traced, IReadOnlyList<TraceLine> autoWrong, CancellationToken cancellationToken)
	{
		var results = autoWrong.Select(classifier.Classify).ToList();
		var set = autoWrong.Count > 0 ? autoWrong[0].Set : string.Empty;

		await writers.Error.WriteLineAsync($"autoWrongCensus set={set} traced={traced} autoWrong={results.Count}").ConfigureAwait(false);
		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation).ThenBy(g => g.Key.Site))
		{
			await writers.Error.WriteLineAsync($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}").ConfigureAwait(false);
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		await writers.Error.WriteLineAsync(
			results.Count > 0
				? $"other={otherCount}/{results.Count} ({otherCount * 100.0 / results.Count:0.0}%)".Replace("other=0/0", "other=0")
				: "other=0").ConfigureAwait(false);

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key).ToList();
		if (missing.Count > 0)
		{
			await writers.Error.WriteLineAsync("missingFields: " + string.Join(", ", missing.Select(g => $"{g.Key}={g.Count()}"))).ConfigureAwait(false);
		}

		var overrideResults = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideResults.Count > 0)
		{
			await writers.Error.WriteLineAsync($"overrideKey yes={overrideResults.Count(r => r.OverrideKey == "yes")} no={overrideResults.Count(r => r.OverrideKey == "no")}").ConfigureAwait(false);
		}

		var reuseResults = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseResults.Count > 0)
		{
			var falseReuse = 0;
			foreach (var r in reuseResults)
			{
				var line = autoWrong.Single(l => l.HoldoutId == r.HoldoutId && l.LineIndex == r.LineIndex);
				var linked = FirstAtom(line).LinkedIngredientId;
				if (linked is null || string.IsNullOrWhiteSpace(r.ParsedName))
				{
					continue;
				}

				if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(r.ParsedName), linked))
				{
					falseReuse++;
				}
			}

			await writers.Error.WriteLineAsync($"reuse-site lines={reuseResults.Count} ShouldReuse(parsedName,linkedIngredientId) false={falseReuse}").ConfigureAwait(false);
		}

		var tierResults = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierResults.Count > 0)
		{
			await writers.Error.WriteLineAsync($"row-choice-tier keyHigher={tierResults.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} acceptedHigher={tierResults.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}").ConfigureAwait(false);
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			await writers.Error.WriteLineAsync(
				$"qualdiff {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]").ConfigureAwait(false);
		}
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static TraceAtom FirstAtom(TraceLine line) => line.Atoms.Count > 0 ? line.Atoms[0] : throw new InvalidOperationException($"Trace line {line.HoldoutId}#{line.LineIndex} has no atoms.");

	private static string ToTsv(ClassificationResult r) => string.Join('\t',
		Sanitize(r.HoldoutId),
		r.LineIndex,
		Sanitize(r.Set),
		r.Relation,
		r.Site,
		r.OverrideKey,
		Sanitize(r.AcceptedTier),
		Sanitize(r.KeyTier),
		Sanitize(r.AcceptedState),
		Sanitize(r.KeyState),
		Sanitize(r.ParsedName),
		Sanitize(r.KeyHead),
		Sanitize(r.AcceptedDesc),
		Sanitize(r.KeyDesc),
		Sanitize(r.RawText));

	private static string Sanitize(string value)
	{
		if (value.IndexOf('\t') < 0 && value.IndexOf('\n') < 0 && value.IndexOf('\r') < 0)
		{
			return value;
		}

		var builder = new StringBuilder(value.Length);
		foreach (var c in value)
		{
			builder.Append(c is '\t' or '\n' or '\r' ? ' ' : c);
		}

		return builder.ToString();
	}

	private static IReadOnlyList<string> Fold(string text)
	{
		var normalizer = new FdcNormalizer();
		return normalizer.NormalizeToTokens(text).Select(t => IngredientLineResolver.SingularizeToken(t)).ToList();
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		try
		{
			await foreach (var raw in File.ReadLinesAsync(path, cancellationToken).ConfigureAwait(false))
			{
				if (string.IsNullOrWhiteSpace(raw))
				{
					continue;
				}

				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions)
					?? throw new InvalidOperationException($"Trace line at {path} deserialized to null."));
			}
		}
		catch (Exception ex) when (ex is IOException or JsonException or InvalidOperationException)
		{
			await writers.Error.WriteLineAsync($"Could not read trace '{path}': {ex.Message}").ConfigureAwait(false);
			return null;
		}

		return lines;
	}
